504	    private void addOrReplaceTypeConverter(TypeConverter typeConverter, TypeConvertible<?, ?> typeConvertible) {
505	        TypeConverter converter = converters.get(typeConvertible);
506	
507	        if (converter == MISS_CONVERTER) {
508	            // we have previously attempted to convert but missed, so add this converter
509	            converters.put(typeConvertible, typeConverter);
510	            return;
511	        }
512	
513	        // only override it if its different
514	        // as race conditions can lead to many threads trying to promote the same fallback converter
515	        if (typeConverter != converter) {
516	
517	            // add the converter unless we should ignore
518	            boolean add = true;
519	
520	            // if converter is not null then a duplicate exists
521	            if (converter != null) {
522	                add = onTypeConverterExists(typeConverter, typeConvertible, converter);
523	            }
524	
525	            if (add) {
526	                converters.put(typeConvertible, typeConverter);
527	            }
528	        }
529	    }
