18	package org.apache.camel.impl.converter;
19	
20	import java.util.Map;
21	
22	import org.apache.camel.TypeConverter;
23	import org.apache.camel.spi.TypeConvertible;
24	
25	/**
26	 * Helper methods for resolving the type conversions. This is an internal API and not meant for public usages.
27	 * <p>
28	 * In a broader sense: the methods of this code help with traversing the class hierarchy of the types involved in a
29	 * conversion, so that the correct TypeConverter can be used. This is a helper class to CoreTypeConverterRegistry.
30	 * <p>
31	 * In the CoreTypeConverterRegistry class, the registry of types if maintained in a ConcurrentMap that associates a type
32	 * pair with the resolver for it (i.e.: it associates pair representing a conversion from String to Integer to a type
33	 * converter - such as CamelBaseBulkConverterLoader).
34	 * <p>
35	 * NOTE 1: a lot of this code is in the hot path of the core engine, so change with extreme caution to prevent
36	 * performance issues on the core code.
37	 * <p>
38	 * NOTE 2: also, a lot of this code runs rather slow operations, so calling these methods should be avoided as much as
39	 * possible
40	 *
41	 */
42	final class TypeResolverHelper {
43	    private TypeResolverHelper() {
44	
45	    }
46	
47	    /**
48	     * Lookup the type converter in the registry (given a type to convert to and a type to convert from, along with a
49	     * mapping of all known converters)
50	     *
51	     * @param  toType     the type to convert to
52	     * @param  fromType   the type to convert from
53	     * @param  converters the map of all known converters
54	     * @return            the type converter or null if unknown
55	     */
56	    static TypeConverter doLookup(
57	            Class<?> toType, Class<?> fromType, Map<TypeConvertible<?, ?>, TypeConverter> converters) {
58	        return doLookup(new TypeConvertible<>(fromType, toType), converters);
59	    }
60	
61	    private static TypeConverter doLookup(
62	            TypeConvertible<?, ?> typeConvertible, Map<TypeConvertible<?, ?>, TypeConverter> converters) {
63	
64	        // try with base converters first
65	        final TypeConverter typeConverter = converters.get(typeConvertible);
66	        if (typeConverter != null) {
67	            return typeConverter;
68	        }
69	
70	        final TypeConverter superConverterTc = tryMatch(typeConvertible, converters);
71	        if (superConverterTc != null) {
72	            return superConverterTc;
73	        }
74	
75	        final TypeConverter primitiveAwareConverter = tryPrimitive(typeConvertible, converters);
76	        if (primitiveAwareConverter != null) {
77	            return primitiveAwareConverter;
78	        }
79	
80	        // only do these tests as fallback and only on the target type
81	        if (!typeConvertible.getFrom().equals(Object.class)) {
82	
83	            final TypeConverter assignableConverter
84	                    = tryAssignableFrom(typeConvertible, converters);
85	            if (assignableConverter != null) {
86	                return assignableConverter;
87	            }
88	
89	            final TypeConverter objConverter = converters.get(new TypeConvertible<>(Object.class, typeConvertible.getTo()));
90	            if (objConverter != null) {
91	                return objConverter;
92	            }
93	        }
94	
95	        // none found
96	        return null;
97	    }
98	
99	    /**
100	     * Try the base converters. That is, those matching a direct conversion (i.e.: when the from and to types requested
101	     * do exist on the converters' map OR when the from and to types requested match for a _primitive type).
102	     * <p>
103	     * For instance: From String.class, To: int.class (would match a method such as myConverter(String, Integer) or
104	     * myConverter(String, int).
105	     *
106	     * @param  typeConvertible the type converter pair
107	     * @param  converters      the map of all known converters
108	     * @return                 the type converter or null if unknown
109	     */
110	    static TypeConverter tryAssignableFrom(
111	            TypeConvertible<?, ?> typeConvertible, Map<TypeConvertible<?, ?>, TypeConverter> converters) {
112	
113	        /*
114	         Let's try classes derived from this toType: basically it traverses the entries looking for assignable types
115	         matching both the "from type" and the "to type" which are NOT Object (we usually try this later).
116	         */
117	        for (var entry : converters.entrySet()) {
118	            final TypeConvertible<?, ?> key = entry.getKey();
119	            if (key.isAssignableMatch(typeConvertible)) {
120	                return entry.getValue();
121	            } else {
122	                if (typeConvertible.isAssignableMatch(key)) {
123	                    return entry.getValue();
124	                }
125	            }
126	        }
127	
128	        return null;
129	    }
130	
131	    /**
132	     * Try to resolve the TypeConverter by forcing a costly and slow recursive check.
133	     *
134	     * @param  typeConvertible the type converter pair
135	     * @param  converters      the map of all known converters
136	     * @return                 the type converter or null if unknown
137	     */
138	    static TypeConverter tryMatch(
139	            TypeConvertible<?, ?> typeConvertible, Map<TypeConvertible<?, ?>, TypeConverter> converters) {
140	        for (var entry : converters.entrySet()) {
141	            if (entry.getKey().matches(typeConvertible)) {
142	                return entry.getValue();
143	            }
144	
145	        }
146	
147	        return null;
148	    }
149	
150	    /**
151	     * Try to resolve the TypeConverter by forcing a costly and slow recursive check that takes into consideration that
152	     * the target type may have a primitive data type
153	     *
154	     * @param  typeConvertible the type converter pair
155	     * @param  converters      the map of all known converters
156	     * @return                 the type converter or null if unknown
157	     */
158	    static TypeConverter tryPrimitive(
159	            TypeConvertible<?, ?> typeConvertible, Map<TypeConvertible<?, ?>, TypeConverter> converters) {
160	        for (var entry : converters.entrySet()) {
161	            if (entry.getKey().matchesPrimitive(typeConvertible)) {
162	                return entry.getValue();
163	            }
164	
165	        }
166	
167	        return null;
168	    }
169	
170	}
