53	/**
54	 * A class which will auto-discover {@link Converter} objects and methods to pre-load the {@link TypeConverterRegistry}
55	 * of converters on startup.
56	 * <p/>
57	 * This implementation supports scanning for type converters in JAR files. The {@link #META_INF_SERVICES} contains a
58	 * list of packages or FQN class names for {@link Converter} classes. The FQN class names is loaded first and directly
59	 * by the class loader.
60	 * <p/>
61	 * The {@link PackageScanClassResolver} is being used to scan packages for {@link Converter} classes and this procedure
62	 * is slower than loading the {@link Converter} classes directly by its FQN class name. Therefore its recommended to
63	 * specify FQN class names in the {@link #META_INF_SERVICES} file. Likewise the procedure for scanning using
64	 * {@link PackageScanClassResolver} may require custom implementations to work in various containers such as JBoss,
65	 * OSGi, etc.
66	 */
67	public class AnnotationTypeConverterLoader implements TypeConverterLoader {
68	    public static final String META_INF_SERVICES = "META-INF/services/org/apache/camel/TypeConverter";
69	    private static final Logger LOG = LoggerFactory.getLogger(AnnotationTypeConverterLoader.class);
70	    private static final Charset UTF8 = StandardCharsets.UTF_8;
71	    protected final PackageScanClassResolver resolver;
72	    protected final Set<Class<?>> visitedClasses = new HashSet<>();
73	    protected final Set<String> visitedURIs = new HashSet<>();
74	    private final String basePackage;
75	
76	    public AnnotationTypeConverterLoader(PackageScanClassResolver resolver) {
77	        this(resolver, null);
78	    }
79	
80	    public AnnotationTypeConverterLoader(PackageScanClassResolver resolver, String basePackage) {
81	        this.resolver = resolver;
82	        this.basePackage = basePackage;
83	    }
84	
85	    @Override
86	    public void load(TypeConverterRegistry registry) throws TypeConverterLoaderException {
87	        String[] packageNames;
88	
89	        LOG.trace("Searching for {} services", META_INF_SERVICES);
90	        try {
91	            packageNames = findPackageNames();
92	            if (packageNames == null || packageNames.length == 0) {
93	                LOG.debug("No package names found to be used for classpath scanning for annotated type converters.");
94	                return;
95	            }
96	        } catch (Exception e) {
97	            throw new TypeConverterLoaderException(
98	                    "Cannot find package names to be used for classpath scanning for annotated type converters.", e);
99	        }
100	
101	        // if we only have camel-core on the classpath then we have already pre-loaded all its type converters
102	        // but we exposed the "org.apache.camel.core" package in camel-core. This ensures there is at least one
103	        // packageName to scan, which triggers the scanning process. That allows us to ensure that we look for
104	        // META-INF/services in all the JARs.
105	        if (packageNames.length == 1 && "org.apache.camel.core".equals(packageNames[0])) {
106	            LOG.debug("No additional package names found in classpath for annotated type converters.");
107	            // no additional package names found to load type converters so break out
108	            return;
109	        }
110	
111	        // now filter out org.apache.camel.core as its not needed anymore (it was just a dummy)
112	        packageNames = filterUnwantedPackage("org.apache.camel.core", packageNames);
113	
114	        // filter out package names which can be loaded as a class directly so we avoid package scanning which
115	        // is much slower and does not work 100% in all runtime containers
116	        Set<Class<?>> classes = new HashSet<>();
117	        packageNames = filterPackageNamesOnly(resolver, packageNames, classes);
118	        if (!classes.isEmpty()) {
119	            LOG.debug("Loaded {} @Converter classes", classes.size());
120	        }
121	
122	        // if there is any packages to scan and load @Converter classes, then do it
123	        if (packageNames != null && packageNames.length > 0) {
124	            if (LOG.isTraceEnabled()) {
125	                LOG.trace("Found converter packages to scan: {}", String.join(", ", packageNames));
126	            }
127	            Set<Class<?>> scannedClasses = resolver.findAnnotated(Converter.class, packageNames);
128	            if (!scannedClasses.isEmpty()) {
129	                LOG.debug("Found {} packages with {} @Converter classes to load", packageNames.length, scannedClasses.size());
130	                classes.addAll(scannedClasses);
131	            }
132	        }
133	
134	        // load all the found classes into the type converter registry
135	        for (Class<?> type : classes) {
136	            if (acceptClass(type)) {
137	                if (LOG.isTraceEnabled()) {
138	                    LOG.trace("Loading converter class: {}", ObjectHelper.name(type));
139	                }
140	                loadConverterMethods(registry, type);
141	            }
142	        }
143	
144	        // now clear the maps so we do not hold references
145	        visitedClasses.clear();
146	        visitedURIs.clear();
147	    }
148	
149	    /**
150	     * Filters the given list of packages and returns an array of <b>only</b> package names.
151	     * <p/>
152	     * This implementation will check the given list of packages, and if it contains a class name, that class will be
153	     * loaded directly and added to the list of classes. This optimizes the type converter to avoid excessive file
154	     * scanning for .class files.
155	     *
156	     * @param  resolver     the class resolver
157	     * @param  packageNames the package names
158	     * @param  classes      to add loaded @Converter classes
159	     * @return              the filtered package names
160	     */
161	    protected String[] filterPackageNamesOnly(PackageScanClassResolver resolver, String[] packageNames, Set<Class<?>> classes) {
162	        if (packageNames == null || packageNames.length == 0) {
163	            return packageNames;
164	        }
165	
166	        // optimize for CorePackageScanClassResolver
167	        if (resolver.getClassLoaders().isEmpty()) {
168	            return packageNames;
169	        }
170	
171	        // the filtered packages to return
172	        List<String> packages = new ArrayList<>();
173	
174	        // try to load it as a class first
175	        for (String name : packageNames) {
176	            // must be a FQN class name by having an upper case letter
177	            if (StringHelper.isClassName(name)) {
178	                Class<?> clazz = null;
179	                for (ClassLoader loader : resolver.getClassLoaders()) {
180	                    try {
181	                        clazz = ObjectHelper.loadClass(name, loader);
182	                        if (clazz != null) {
183	                            LOG.trace("Loaded {} as class {}", name, clazz);
184	                            classes.add(clazz);
185	                            // class found, so no need to load it with another class loader
186	                        }
187	                        break;
188	                    } catch (Exception e) {
189	                        // do nothing here
190	                    }
191	                }
192	                if (clazz == null) {
193	                    // ignore as its not a class (will be package scan afterwards)
194	                    packages.add(name);
195	                }
196	            } else {
197	                // ignore as its not a class (will be package scan afterwards)
198	                packages.add(name);
199	            }
200	        }
201	
202	        // return the packages which is not FQN classes
203	        return packages.toArray(new String[0]);
204	    }
205	
206	    /**
207	     * Finds the names of the packages to search for on the classpath looking for text files on the classpath at the
208	     * {@link #META_INF_SERVICES} location.
209	     *
210	     * @return             a collection of packages to search for
211	     * @throws IOException is thrown for IO related errors
212	     */
213	    protected String[] findPackageNames() throws IOException {
214	        Set<String> packages = new HashSet<>();
215	        if (basePackage != null) {
216	            String[] pks = basePackage.split(",");
217	            packages.addAll(Arrays.asList(pks));
218	        }
219	        ClassLoader ccl = Thread.currentThread().getContextClassLoader();
220	        if (ccl != null) {
221	            findPackages(packages, ccl);
222	        }
223	        findPackages(packages, getClass().getClassLoader());
224	        return packages.toArray(new String[0]);
225	    }
226	
227	    protected void findPackages(Set<String> packages, ClassLoader classLoader) throws IOException {
228	        Enumeration<URL> resources = classLoader.getResources(META_INF_SERVICES);
229	        while (resources.hasMoreElements()) {
230	            URL url = resources.nextElement();
231	            String path = url.getPath();
232	            if (!visitedURIs.contains(path)) {
233	                // remember we have visited this uri so we wont read it twice
234	                visitedURIs.add(path);
235	                LOG.debug("Loading file {} to retrieve list of packages, from url: {}", META_INF_SERVICES, url);
236	                BufferedReader reader = IOHelper.buffered(new InputStreamReader(url.openStream(), UTF8));
237	                try {
238	                    while (true) {
239	                        String line = reader.readLine();
240	                        if (line == null) {
241	                            break;
242	                        }
243	                        line = line.trim();
244	                        if (line.startsWith("#") || line.isEmpty()) {
245	                            continue;
246	                        }
247	                        tokenize(packages, line);
248	                    }
249	                } finally {
250	                    IOHelper.close(reader, null, LOG);
251	                }
252	            }
253	        }
254	    }
255	
256	    /**
257	     * Tokenizes the line from the META-IN/services file using commas and ignoring whitespace between packages
258	     */
259	    private void tokenize(Set<String> packages, String line) {
260	        StringTokenizer iter = new StringTokenizer(line, ",");
261	        while (iter.hasMoreTokens()) {
262	            String name = iter.nextToken().trim();
263	            if (!name.isEmpty()) {
264	                packages.add(name);
265	            }
266	        }
267	    }
268	
269	    /**
270	     * Loads all of the converter methods for the given type
271	     */
272	    protected void loadConverterMethods(TypeConverterRegistry registry, Class<?> type) {
273	        if (visitedClasses.contains(type)) {
274	            return;
275	        }
276	        visitedClasses.add(type);
277	        try {
278	            Method[] methods = type.getDeclaredMethods();
279	            CachingInjector<?> injector = null;
280	
281	            for (Method method : methods) {
282	                // this may be prone to ClassLoader or packaging problems when the same class is defined
283	                // in two different jars (as is the case sometimes with specs).
284	                if (AnnotationHelper.hasAnnotation(method, Converter.class, true)) {
285	                    boolean allowNull = false;
286	                    if (method.getAnnotation(Converter.class) != null) {
287	                        allowNull = method.getAnnotation(Converter.class).allowNull();
288	                    }
289	                    boolean fallback = method.getAnnotation(Converter.class).fallback();
290	                    if (fallback) {
291	                        injector = handleHasFallbackConverterAnnotation(registry, type, injector, method, allowNull);
292	                    } else {
293	                        injector = handleHasConverterAnnotation(registry, type, injector, method, allowNull);
294	                    }
295	                }
296	            }
297	
298	            Class<?> superclass = type.getSuperclass();
299	            if (superclass != null && !superclass.equals(Object.class)) {
300	                loadConverterMethods(registry, superclass);
301	            }
302	        } catch (NoClassDefFoundError e) {
303	            boolean ignore = false;
304	            // does the class allow to ignore the type converter when having load errors
305	            if (AnnotationHelper.hasAnnotation(type, Converter.class, true)) {
306	                if (type.getAnnotation(Converter.class) != null) {
307	                    ignore = type.getAnnotation(Converter.class).ignoreOnLoadError();
308	                }
309	            }
310	            // if we should ignore then only log at debug level
311	            if (ignore) {
312	                LOG.debug("Ignoring converter type: {} as a dependent class could not be found: {}",
313	                        type.getCanonicalName(), e, e);
314	            } else {
315	                LOG.warn("Ignoring converter type: {} as a dependent class could not be found: {}",
316	                        type.getCanonicalName(), e, e);
317	            }
318	        }
319	    }
320	
321	    protected boolean acceptClass(Class<?> clazz) {
322	        return true;
323	    }
324	
325	    private CachingInjector<?> handleHasConverterAnnotation(
326	            TypeConverterRegistry registry, Class<?> type,
327	            CachingInjector<?> injector, Method method, boolean allowNull) {
328	        if (isValidConverterMethod(method)) {
329	            int modifiers = method.getModifiers();
330	            if (isAbstract(modifiers) || !isPublic(modifiers)) {
331	                LOG.warn(
332	                        "Ignoring bad converter on type: {} method: {} as a converter method is not a public and concrete method",
333	                        type.getCanonicalName(), method);
334	            } else {
335	                Class<?> toType = method.getReturnType();
336	                if (toType.equals(Void.class)) {
337	                    LOG.warn("Ignoring bad converter on type: {} method: {} as a converter method returns a void method",
338	                            type.getCanonicalName(), method);
339	                } else {
340	                    Class<?> fromType = method.getParameterTypes()[0];
341	                    if (isStatic(modifiers)) {
342	                        registerTypeConverter(registry, method, toType, fromType,
343	                                new StaticMethodTypeConverter(method, allowNull));
344	                    } else {
345	                        if (injector == null) {
346	                            injector = new CachingInjector<>(registry, CastUtils.cast(type, Object.class));
347	                        }
348	                        registerTypeConverter(registry, method, toType, fromType,
349	                                new InstanceMethodTypeConverter(injector, method, registry, allowNull));
350	                    }
351	                }
352	            }
353	        } else {
354	            LOG.warn("Ignoring bad converter on type: {} method: {} as a converter method should have one parameter",
355	                    type.getCanonicalName(), method);
356	        }
357	        return injector;
358	    }
359	
360	    private CachingInjector<?> handleHasFallbackConverterAnnotation(
361	            TypeConverterRegistry registry, Class<?> type,
362	            CachingInjector<?> injector, Method method, boolean allowNull) {
363	        if (isValidFallbackConverterMethod(method)) {
364	            int modifiers = method.getModifiers();
365	            if (isAbstract(modifiers) || !isPublic(modifiers)) {
366	                LOG.warn("Ignoring bad fallback converter on type: {} method: {} as a fallback converter method is not "
367	                         + "a public and concrete method",
368	                        type.getCanonicalName(), method);
369	            } else {
370	                Class<?> toType = method.getReturnType();
371	                if (toType.equals(Void.class)) {
372	                    LOG.warn("Ignoring bad fallback converter on type: {} method: {} as a fallback converter method "
373	                             + "returns a void method",
374	                            type.getCanonicalName(), method);
375	                } else {
376	                    if (isStatic(modifiers)) {
377	                        registerFallbackTypeConverter(registry,
378	                                new StaticMethodFallbackTypeConverter(method, registry, allowNull), method);
379	                    } else {
380	                        if (injector == null) {
381	                            injector = new CachingInjector<>(registry, CastUtils.cast(type, Object.class));
382	                        }
383	                        registerFallbackTypeConverter(registry,
384	                                new InstanceMethodFallbackTypeConverter(injector, method, registry, allowNull), method);
385	                    }
386	                }
387	            }
388	        } else {
389	            LOG.warn("Ignoring bad fallback converter on type: {} method: {} as a fallback converter method should have "
390	                     + "one parameter",
391	                    type.getCanonicalName(), method);
392	        }
393	        return injector;
394	    }
395	
396	    protected void registerTypeConverter(
397	            TypeConverterRegistry registry,
398	            Method method, Class<?> toType, Class<?> fromType, TypeConverter typeConverter) {
399	        registry.addTypeConverter(toType, fromType, typeConverter);
400	    }
401	
402	    protected boolean isValidConverterMethod(Method method) {
403	        Class<?>[] parameterTypes = method.getParameterTypes();
404	        return parameterTypes.length == 1 || parameterTypes.length == 2 && Exchange.class.isAssignableFrom(parameterTypes[1]);
405	    }
406	
407	    protected void registerFallbackTypeConverter(TypeConverterRegistry registry, TypeConverter typeConverter, Method method) {
408	        boolean canPromote = false;
409	        // check whether the annotation may indicate it can promote
410	        if (method.getAnnotation(Converter.class) != null) {
411	            canPromote = method.getAnnotation(Converter.class).fallbackCanPromote();
412	        }
413	        registry.addFallbackTypeConverter(typeConverter, canPromote);
414	    }
415	
416	    protected boolean isValidFallbackConverterMethod(Method method) {
417	        Class<?>[] parameterTypes = method.getParameterTypes();
418	        return parameterTypes.length == 3 || parameterTypes.length == 4 && Exchange.class.isAssignableFrom(parameterTypes[1])
419	                && TypeConverterRegistry.class.isAssignableFrom(parameterTypes[parameterTypes.length - 1]);
420	    }
421	
422	    /**
423	     * Filters the given list of packages
424	     *
425	     * @param  name         the name to filter out
426	     * @param  packageNames the packages
427	     * @return              he packages without the given name
428	     */
429	    protected static String[] filterUnwantedPackage(String name, String[] packageNames) {
430	        // the filtered packages to return
431	        List<String> packages = new ArrayList<>();
432	
433	        for (String s : packageNames) {
434	            if (!name.equals(s)) {
435	                packages.add(s);
436	            }
437	        }
438	
439	        return packages.toArray(new String[0]);
440	    }
