29	/**
30	 * The default implementation of {@link org.apache.camel.Message}
31	 * <p/>
32	 * This implementation uses a {@link org.apache.camel.util.CaseInsensitiveMap} storing the headers. This allows us to be
33	 * able to lookup headers using case insensitive keys, making it easier for end users as they do not have to be worried
34	 * about using exact keys. See more details at {@link org.apache.camel.util.CaseInsensitiveMap}. The implementation of
35	 * the map can be configured by the {@link HeadersMapFactory} which can be set on the {@link CamelContext}. The default
36	 * implementation uses the {@link org.apache.camel.util.CaseInsensitiveMap CaseInsensitiveMap}.
37	 */
38	public class DefaultMessage extends MessageSupport {
39	    private Map<String, Object> headers;
40	
41	    public DefaultMessage(Exchange exchange) {
42	        setExchange(exchange);
43	        if (exchange != null) {
44	            setCamelContext(exchange.getContext());
45	        }
46	    }
