49	        this.camelContext = camelContext;
50	        this.typeConverter = camelContext.getTypeConverter();
51	    }
52	
53	    @Override
54	    public void reset() {
55	        super.reset();
56	        if (headers instanceof CopyOnWriteHeadersMap) {
57	            headers = null;
58	        } else if (headers != null) {
59	            headers.clear();
60	        }
61	        removeTrait(MessageTrait.ATTACHMENTS);
62	    }
