87	    @Override
88	    @SuppressWarnings("unchecked")
89	    public <T> T getHeader(String name, Class<T> type) {
90	        Object value = getHeader(name);
91	        if (value == null) {
92	            if (boolean.class == type) {
93	                return (T) Boolean.FALSE;
94	            }
95	            return null;
96	        }
97	
98	        if (type.isInstance(value)) {
99	            return (T) value;
100	        }
101	
102	        Exchange e = getExchange();
103	        if (e != null) {
104	            return typeConverter.convertTo(type, e, value);
105	        } else {
106	            return typeConverter.convertTo(type, value);
107	        }
108	    }
