110	    @Override
111	    @SuppressWarnings("unchecked")
112	    public <T> T getHeader(String name, Object defaultValue, Class<T> type) {
113	        Object value = getHeader(name);
114	        if (value == null) {
115	            value = defaultValue;
116	        }
117	        if (value == null) {
118	            if (boolean.class == type) {
119	                return (T) Boolean.FALSE;
120	            }
121	            return null;
122	        }
123	
124	        if (type.isInstance(value)) {
125	            return (T) value;
126	        }
127	
128	        Exchange e = getExchange();
129	        if (e != null) {
130	            return typeConverter.convertTo(type, e, value);
131	        } else {
132	            return typeConverter.convertTo(type, value);
133	        }
134	    }
