136	    @Override
137	    @SuppressWarnings("unchecked")
138	    public <T> T getHeader(String name, Supplier<Object> defaultValueSupplier, Class<T> type) {
139	        Object value = getHeader(name, defaultValueSupplier);
140	        if (value == null) {
141	            // lets avoid NullPointerException when converting to boolean for null values
142	            if (boolean.class == type) {
143	                return (T) Boolean.FALSE;
144	            }
145	            return null;
146	        }
147	
148	        // eager same instance type test to avoid the overhead of invoking the type converter
149	        // if already same type
150	        if (type.isInstance(value)) {
151	            return type.cast(value);
152	        }
153	
154	        Exchange e = getExchange();
155	        if (e != null) {
156	            return typeConverter.convertTo(type, e, value);
157	        } else {
158	            return typeConverter.convertTo(type, value);
159	        }
160	    }
