167	    @Override
168	    public Object removeHeader(String name) {
169	        if (headers == null) {
170	            if (!isPopulateHeadersSupported()) {
171	                return null;
172	            }
173	            headers = createHeaders();
174	        }
175	        return headers.remove(name);
