178	    @Override
179	    public boolean removeHeaders(String pattern) {
180	        return removeHeaders(pattern, (String[]) null);
181	    }
182	
183	    @Override
184	    public boolean removeHeaders(String pattern, String... excludePatterns) {
185	        if (headers == null) {
186	            if (!isPopulateHeadersSupported()) {
187	                return false;
188	            }
189	            headers = createHeaders();
190	        }
191	        if (headers.isEmpty()) {
192	            return false;
193	        }
194	        Map<String, Object> h = headers;
195	
196	        // special optimized
197	        if (excludePatterns == null && "*".equals(pattern)) {
198	            h.clear();
199	            return true;
200	        }
201	
202	        final Set<String> toBeRemoved = PatternHelper.matchingSet(h, pattern, excludePatterns);
203	
204	        if (toBeRemoved != null) {
205	            if (toBeRemoved.size() == h.size()) {
206	                h.clear();
207	            } else {
208	                for (String key : toBeRemoved) {
209	                    h.remove(key);
210	                }
211	            }
212	
213	            return true;
214	        }
215	
216	        return false;
217	    }
