234	                // create a new map
235	                this.headers = camelContext.getCamelContextExtension().getHeadersMapFactory().newMap(headers);
236	            }
237	        } else {
238	            // should not really happen but some tests rely on using camel context that is not started
239	            this.headers = new HashMap<>(headers);
240	        }
241	    }
