119	        // eager same instance type test to avoid the overhead of invoking the type converter
120	        // if already same type
121	        if (type.isInstance(body)) {
122	            return (T) body;
123	        }
124	
125	        Exchange e = getExchange();
126	        if (e != null) {
127	            try {
128	                return typeConverter.mandatoryConvertTo(type, e, getBody());
