144	    }
145	
146	    @Override
147	    public <T> void setBody(Object value, Class<T> type) {
148	        Exchange e = getExchange();
149	        if (e != null) {
150	            T v = typeConverter.convertTo(type, e, value);
151	            if (v != null) {
152	                value = v;
153	            }
154	        }
155	        setBody(value);
156	    }
157	
158	    @Override
159	    public void setBody(Object body, DataType type) {
160	        this.body = body;
161	        setPayloadForTrait(MessageTrait.DATA_AWARE, type);
162	    }
163	
164	    @Override
165	    public DataType getDataType() {
166	        Object payload = getPayloadForTrait(MessageTrait.DATA_AWARE);
167	        return (DataType) payload;
168	    }
169	
170	    @Override
171	    public void setDataType(DataType type) {
172	        setPayloadForTrait(MessageTrait.DATA_AWARE, type);
173	    }
174	
175	    @Override
176	    public boolean hasDataType() {
177	        return hasTrait(MessageTrait.DATA_AWARE);
178	    }
179	
180	    @Override
181	    public Message copy() {
182	        Message answer = newInstance();
183	
184	        answer.copyFrom(this);
185	        return answer;
186	    }
187	
188	    @Override
189	    public void copyFrom(Message that) {
190	        if (that == this) {
191	            // it's the same instance, so do not need to copy
192	            return;
193	        }
194	
195	        copyFromWithNewBody(that, that.getBody());
196	        // Preserve the DataType
197	        if (that.hasTrait(MessageTrait.DATA_AWARE)) {
198	            setPayloadForTrait(MessageTrait.DATA_AWARE, that.getPayloadForTrait(MessageTrait.DATA_AWARE));
199	        }
200	    }
201	
202	    @Override
203	    @SuppressWarnings("raw")
204	    public void copyFromWithNewBody(Message that, Object newBody) {
205	        if (that == this) {
206	            // it's the same instance, so do not need to copy
207	            return;
208	        }
209	
210	        // cover over exchange if none has been assigned
211	        if (getExchange() == null) {
212	            setExchange(that.getExchange());
213	        }
214	
215	        if (that.hasMessageId()) {
216	            setMessageId(that.getMessageId());
217	        }
218	        // should likely not set DataType as the new body may be a different type than the original body
219	        setBody(newBody);
220	
221	        // the headers may be the same instance if the end user has made some mistake
222	        // and set the OUT message with the same header instance of the IN message etc
223	        if (!sameHeaders(that)) {
224	            if (that instanceof DefaultMessage thatDefault && this instanceof DefaultMessage thisDefault) {
225	                thisDefault.copyHeadersFrom(thatDefault);
226	            } else {
227	                setHeaders(that.getHeaders());
228	            }
229	        }
230	
231	        // copy attachments
232	        Map<String, Object> attachments = (Map<String, Object>) that.getPayloadForTrait(MessageTrait.ATTACHMENTS);
233	        if (attachments != null) {
234	            setPayloadForTrait(MessageTrait.ATTACHMENTS, new LinkedHashMap<>(attachments));
235	        }
236	    }
237	
238	    private boolean sameHeaders(Message that) {
239	        return hasHeaders() && that.hasHeaders() && getHeaders() == that.getHeaders();
240	    }
241	
242	    @Override
243	    public Exchange getExchange() {
244	        return exchange;
245	    }
246	
247	    public void setExchange(Exchange exchange) {
248	        this.exchange = exchange;
249	    }
