98	    public <T> T convertTo(Class<T> type, Object value) {
99	        return convertTo(type, null, value);
100	    }
101	
102	    @SuppressWarnings("unchecked")
103	    private <T> T fastConvertTo(Class<T> type, Exchange exchange, Object value) {
104	        if (value == null) {
105	            return null;
106	        }
107	
108	        if (type.equals(value.getClass())) {
109	            // same instance
110	            return (T) value;
111	        }
112	
113	        if (type == boolean.class) {
114	            // primitive boolean which must return a value so throw exception if not possible
115	            Object answer = ObjectConverter.toBoolean(value);
116	            requireNonNullBoolean(type, value, answer);
117	            return (T) answer;
118	        } else if (type == Boolean.class && value instanceof String str) {
119	            // String -> Boolean
120	            Boolean parsedBoolean = customParseBoolean(str);
121	            if (parsedBoolean != null) {
122	                return (T) parsedBoolean;
123	            }
124	        } else if (type.isPrimitive()) {
125	            // okay its a wrapper -> primitive then return as-is for some common types
126	            Class<?> cls = value.getClass();
127	            if (cls == Integer.class || cls == Long.class) {
128	                return (T) value;
129	            }
130	        } else if (type == String.class) {
131	            // okay its a primitive -> string then return as-is for some common types
132	            Class<?> cls = value.getClass();
133	            if (cls.isPrimitive()
134	                    || cls == Boolean.class
135	                    || cls == Integer.class
136	                    || cls == Long.class) {
137	                return (T) value.toString();
138	            }
139	        } else if (type.isEnum()) {
140	            // okay its a conversion to enum
141	            try {
142	                return enumTypeConverter.convertTo(type, exchange, value);
143	            } catch (Exception e) {
144	                throw createTypeConversionException(exchange, type, value, e);
145	            }
146	        }
147	
148	        // NOTE: we cannot optimize any more if value is String as it may be time pattern and other patterns
149	        return null;
150	    }
151	
152	    @SuppressWarnings("unchecked")
153	    public <T> T convertTo(Class<T> type, Exchange exchange, Object value) {
154	        // optimize for a few common conversions
155	
156	        if (value != null) {
157	            T ret = fastConvertTo(type, exchange, value);
158	            if (ret == Void.class) {
159	                return null;
160	            }
161	            if (ret != null) {
162	                return ret;
163	            }
164	
165	            // NOTE: we cannot optimize any more if value is String as it may be time pattern and other patterns
166	        }
167	
168	        Object answer = doConvertToAndStat(type, exchange, value, false);
169	        if (answer == Void.class) {
170	            answer = null;
171	        }
172	        return (T) answer;
173	    }
174	
175	    private static Boolean customParseBoolean(String str) {
176	        if ("true".equalsIgnoreCase(str)) {
177	            return Boolean.TRUE;
178	        }
179	
180	        if ("false".equalsIgnoreCase(str)) {
181	            return Boolean.FALSE;
182	        }
183	
184	        return null;
185	    }
186	
187	    public <T> T mandatoryConvertTo(Class<T> type, Object value) throws NoTypeConversionAvailableException {
188	        return mandatoryConvertTo(type, null, value);
189	    }
190	
191	    @SuppressWarnings("unchecked")
192	    public <T> T mandatoryConvertTo(Class<T> type, Exchange exchange, Object value) throws NoTypeConversionAvailableException {
193	        // optimize for a few common conversions
194	        if (value != null) {
195	            T ret = fastConvertTo(type, exchange, value);
196	            if (ret != null) {
197	                return ret;
198	            }
199	        }
200	
201	        Object answer = doConvertToAndStat(type, exchange, value, false);
202	        if (answer == Void.class) {
203	            return null;
204	        }
205	        if (answer == null) {
206	            // Could not find suitable conversion
207	            throw new NoTypeConversionAvailableException(value, type);
208	        }
209	        return (T) answer;
210	    }
211	
212	    public <T> T tryConvertTo(Class<T> type, Object value) {
213	        return tryConvertTo(type, null, value);
214	    }
215	
216	    @SuppressWarnings("unchecked")
217	    public <T> T tryConvertTo(Class<T> type, Exchange exchange, Object value) {
218	        // optimize for a few common conversions
219	        if (value != null) {
220	            if (type.isInstance(value)) {
221	                // same instance
222	                return (T) value;
223	            }
224	            if (type == boolean.class) {
225	                // primitive boolean which must return a value so throw exception if not possible
226	                Object answer = ObjectConverter.toBoolean(value);
227	                requireNonNullBoolean(type, value, answer);
228	                return (T) answer;
229	            } else if (type == Boolean.class && value instanceof String str) {
230	                // String -> Boolean
231	                Boolean parsedBoolean = customParseBoolean(str);
232	                if (parsedBoolean != null) {
233	                    return (T) parsedBoolean;
234	                }
235	            } else if (type.isPrimitive()) {
236	                // okay its a wrapper -> primitive then return as-is for some common types
237	                Class<?> cls = value.getClass();
238	                if (cls == Integer.class || cls == Long.class) {
239	                    return (T) value;
240	                }
241	            } else if (type == String.class) {
242	                // okay its a primitive -> string then return as-is for some common types
243	                Class<?> cls = value.getClass();
244	                if (cls.isPrimitive()
245	                        || cls == Boolean.class
246	                        || cls == Integer.class
247	                        || cls == Long.class) {
248	                    return (T) value.toString();
249	                }
250	            } else if (type.isEnum()) {
251	                // okay its a conversion to enum
252	                try {
253	                    return enumTypeConverter.convertTo(type, exchange, value);
254	                } catch (Exception e) {
255	                    // we are only trying so ignore exceptions
256	                    return null;
257	                }
258	            }
259	
260	            // NOTE: we cannot optimize any more if value is String as it may be time pattern and other patterns
261	        }
262	
263	        Object answer = doConvertToAndStat(type, exchange, value, true);
264	        if (answer == Void.class) {
265	            return null;
266	        }
267	        return (T) answer;
268	    }
269	
270	    private static <T> void requireNonNullBoolean(Class<T> type, Object value, Object answer) {
271	        if (answer == null) {
272	            throw new TypeConversionException(
273	                    value, type,
274	                    new IllegalArgumentException("Cannot convert type: " + value.getClass().getName() + " to boolean"));
275	        }
276	    }
277	
278	    protected Object doConvertToAndStat(
279	            final Class<?> type, final Exchange exchange, final Object value,
280	            final boolean tryConvert) {
281	
282	        Object answer = null;
283	        try {
284	            answer = doConvertTo(type, exchange, value, tryConvert);
285	        } catch (Exception e) {
286	            // only record if not try
287	            if (!tryConvert) {
288	                statistics.incrementFailed();
289	            }
290	
291	            if (tryConvert) {
292	                return null;
293	            }
294	
295	            wrapConversionException(type, exchange, value, e);
296	        }
297	        if (answer == TypeConverter.MISS_VALUE) {
298	            if (!tryConvert) {
299	                // Could not find suitable conversion
300	                statistics.incrementMiss();
301	            }
302	
303	            return null;
304	        } else {
305	            if (!tryConvert) {
306	                statistics.incrementHit();
307	            }
308	            return answer;
309	        }
310	    }
311	
312	    private void wrapConversionException(Class<?> type, Exchange exchange, Object value, Exception e) {
313	        // if its a ExecutionException then we have rethrow it as its not due to failed conversion
314	        // this is special for FutureTypeConverter
315	        boolean execution = ObjectHelper.getException(ExecutionException.class, e) != null
316	                || ObjectHelper.getException(CamelExecutionException.class, e) != null;
317	        if (execution) {
318	            throw CamelExecutionException.wrapCamelExecutionException(exchange, e);
319	        }
320	        // error occurred during type conversion
321	        throw createTypeConversionException(exchange, type, value, e);
322	    }
323	
324	    private static Object nullToPrimitiveType(final Class<?> type) {
325	        if (boolean.class == type) {
326	            return Boolean.FALSE;
327	        }
328	        if (int.class == type) {
329	            return 0;
330	        }
331	        if (long.class == type) {
332	            return 0L;
333	        }
334	        if (byte.class == type) {
335	            return (byte) 0;
336	        }
337	        if (short.class == type) {
338	            return (short) 0;
339	        }
340	        if (double.class == type) {
341	            return 0.0;
342	        }
343	        if (float.class == type) {
344	            return 0.0f;
345	        }
346	        if (char.class == type) {
347	            return '\0';
348	        }
349	
350	        return null;
351	    }
352	
353	    protected Object doConvertTo(
354	            final Class<?> type, final Exchange exchange, final Object value,
355	            final boolean tryConvert) {
356	
357	        if (value == null) {
358	            // no type conversion was needed
359	            if (!tryConvert) {
360	                statistics.incrementNoop();
361	            }
362	
363	            // lets avoid NullPointerException when converting to primitives for null values
364	            if (type.isPrimitive()) {
365	                return nullToPrimitiveType(type);
366	            }
367	            return null;
368	        }
369	
370	        // same instance type
371	        if (type.isInstance(value)) {
372	            // no type conversion was needed
373	
374	            if (!tryConvert) {
375	                statistics.incrementNoop();
376	            }
377	
378	            return value;
379	        }
380	
381	        if (!tryConvert) {
382	            statistics.incrementAttempt();
383	        }
384	
385	        // attempt bulk first which is the fastest (also taking into account primitives)
386	        final Class<?> aClass = type.isPrimitive() ? ObjectHelper.convertPrimitiveTypeToWrapperType(type) : type;
387	        final TypeConvertible<?, ?> typeConvertible = new TypeConvertible<>(value.getClass(), aClass);
388	
389	        final Object ret = tryCachedConverters(type, exchange, value, typeConvertible);
390	        if (ret != null) {
391	            return ret;
392	        }
393	
394	        // fallback converters
395	        final Object fallBackRet = tryFallback(type, exchange, value, tryConvert, typeConvertible);
396	        if (fallBackRet != null) {
397	            return fallBackRet;
398	        }
399	
400	        final TypeConverter assignableConverter = tryAssignableFrom(typeConvertible, converters);
401	        if (assignableConverter != null) {
402	            converters.put(typeConvertible, assignableConverter);
403	            return assignableConverter.convertTo(type, exchange, value);
404	        }
405	
406	        // This is the last resort: if nothing else works, try to find something that converts from an Object to the target type
407	        final TypeConverter objConverter = converters.get(new TypeConvertible<>(Object.class, type));
408	        if (objConverter != null) {
409	            converters.put(typeConvertible, objConverter);
410	            return objConverter.convertTo(type, exchange, value);
411	        }
412	
413	        if (!tryConvert) {
414	            converters.put(typeConvertible, MISS_CONVERTER);
415	        }
416	
417	        // Could not find suitable conversion, so return Void to indicate not found
418	        return TypeConverter.MISS_VALUE;
419	    }
420	
421	    private Object tryCachedConverters(Class<?> type, Exchange exchange, Object value, TypeConvertible<?, ?> typeConvertible) {
422	        final TypeConverter typeConverter = converters.get(typeConvertible);
423	        if (typeConverter != null) {
424	            final Object ret = typeConverter.convertTo(type, exchange, value);
425	            if (ret != null) {
426	                return ret;
427	            }
428	        }
429	
430	        final TypeConverter superConverterTc = TypeResolverHelper.tryMatch(typeConvertible, converters);
431	        if (superConverterTc != null) {
432	            final Object ret = superConverterTc.convertTo(type, exchange, value);
433	            if (ret != null) {
434	                converters.put(typeConvertible, superConverterTc);
435	                return ret;
436	            }
437	        }
438	
439	        return null;
440	    }
441	
442	    private Object tryFallback(
443	            final Class<?> type, final Exchange exchange, final Object value, boolean tryConvert,
444	            TypeConvertible<?, ?> typeConvertible) {
445	        for (FallbackTypeConverter fallback : fallbackConverters) {
446	            TypeConverter tc = fallback.getFallbackTypeConverter();
447	
448	            Object rc = doConvert(type, exchange, value, tryConvert, tc);
449	            if (rc == null && tc.allowNull()) {
450	                return null;
451	            }
452	
453	            if (rc == TypeConverter.MISS_VALUE) {
454	                // it cannot be converted so give up
455	                return TypeConverter.MISS_VALUE;
456	            }
457	
458	            if (rc != null) {
459	                converters.put(typeConvertible, tc);
460	                // if fallback can promote then let it be promoted to a first class type converter
461	                if (fallback.isCanPromote()) {
462	                    // add it as a known type converter since we found a fallback that could do it
463	                    addOrReplaceTypeConverter(tc, typeConvertible);
464	                }
465	                // return converted value
466	                return rc;
467	            }
468	        }
469	
470	        return null;
471	    }
472	
473	    private static Object doConvert(
474	            Class<?> type, Exchange exchange, Object value, boolean tryConvert, TypeConverter converter) {
475	
476	        if (tryConvert) {
477	            return converter.tryConvertTo(type, exchange, value);
478	        } else {
479	            return converter.convertTo(type, exchange, value);
480	        }
481	    }
