497	    public void addTypeConverter(Class<?> toType, Class<?> fromType, TypeConverter typeConverter) {
498	        LOG.trace("Adding type converter: {}", typeConverter);
499	        final TypeConvertible<?, ?> typeConvertible = new TypeConvertible<>(fromType, toType);
500	
501	        addOrReplaceTypeConverter(typeConverter, typeConvertible);
502	    }
503	
504	    private void addOrReplaceTypeConverter(TypeConverter typeConverter, TypeConvertible<?, ?> typeConvertible) {
505	        TypeConverter converter = converters.get(typeConvertible);
506	
507	        if (converter == MISS_CONVERTER) {
508	            // we have previously attempted to convert but missed, so add this converter
509	            converters.put(typeConvertible, typeConverter);
510	            return;
511	        }
512	
513	        // only override it if its different
514	        // as race conditions can lead to many threads trying to promote the same fallback converter
515	        if (typeConverter != converter) {
516	
517	            // add the converter unless we should ignore
518	            boolean add = true;
519	
520	            // if converter is not null then a duplicate exists
521	            if (converter != null) {
522	                add = onTypeConverterExists(typeConverter, typeConvertible, converter);
523	            }
524	
525	            if (add) {
526	                converters.put(typeConvertible, typeConverter);
527	            }
528	        }
529	    }
530	
531	    private boolean onTypeConverterExists(
532	            TypeConverter typeConverter, TypeConvertible<?, ?> typeConvertible, TypeConverter converter) {
533	        if (typeConverterExists == TypeConverterExists.Override) {
534	            CamelLogger logger = new CamelLogger(LOG, typeConverterExistsLoggingLevel);
535	            logger.log("Overriding type converter from: " + converter + " to: " + typeConverter);
536	
537	            return true;
538	        } else if (typeConverterExists == TypeConverterExists.Ignore) {
539	            CamelLogger logger = new CamelLogger(LOG, typeConverterExistsLoggingLevel);
540	            logger.log("Ignoring duplicate type converter from: " + converter + " to: " + typeConverter);
541	            return false;
542	        }
543	
544	        // we should fail
545	        throw new TypeConverterExistsException(typeConvertible.getTo(), typeConvertible.getFrom());
546	    }
