548	    public boolean removeTypeConverter(Class<?> toType, Class<?> fromType) {
549	        LOG.trace("Removing type converter from: {} to: {}", fromType, toType);
550	        final TypeConverter removed = converters.remove(new TypeConvertible<>(fromType, toType));
551	        return removed != null;
552	    }
