559	    public void addFallbackTypeConverter(TypeConverter typeConverter, boolean canPromote) {
560	        LOG.trace("Adding fallback type converter: {} which can promote: {}", typeConverter, canPromote);
561	
562	        // add in top of fallback as the toString() fallback will nearly always be able to convert
563	        // the last one which is add to the FallbackTypeConverter will be called at the first place
564	        fallbackConverters.add(0, new FallbackTypeConverter(typeConverter, canPromote));
565	    }
