571	    @Override
572	    public Map<Class<?>, TypeConverter> lookup(Class<?> toType) {
573	        Map<Class<?>, TypeConverter> answer = new LinkedHashMap<>();
574	        for (var e : converters.entrySet()) {
575	            Class<?> target = e.getKey().getTo();
576	            if (target == toType) {
577	                answer.put(e.getKey().getFrom(), e.getValue());
578	            }
579	        }
580	        return answer;
581	    }
