583	    @Deprecated(since = "4.0.0")
584	    protected TypeConverter getOrFindTypeConverter(Class<?> toType, Class<?> fromType) {
585	        TypeConvertible<?, ?> typeConvertible = new TypeConvertible<>(fromType, toType);
586	
587	        TypeConverter converter = converters.get(typeConvertible);
588	        if (converter == null) {
589	            // converter not found, try to lookup then
590	            converter = lookup(toType, fromType);
591	            if (converter != null) {
592	                converters.put(typeConvertible, converter);
593	            }
594	        }
595	        return converter;
596	    }
