602	    protected TypeConversionException createTypeConversionException(
603	            Exchange exchange, Class<?> type, Object value, Throwable cause) {
604	        if (cause instanceof TypeConversionException tce) {
605	            if (tce.getToType() == type) {
606	                return (TypeConversionException) cause;
607	            }
608	        }
609	        Object body;
610	        // extract the body for logging which allows to limit the message body in the exception/stacktrace
611	        // and also can be used to turn off logging sensitive message data
612	        if (exchange != null) {
613	            body = MessageHelper.extractValueForLogging(value, exchange.getIn());
614	        } else {
615	            body = value;
616	        }
617	        return new TypeConversionException(body, type, cause);
618	    }
