45	import org.slf4j.LoggerFactory;
46	
47	/**
48	 * Base implementation of a type converter registry used for <a href="http://camel.apache.org/type-converter.html">type
49	 * converters</a> in Camel.
50	 */
51	public abstract class BaseTypeConverterRegistry extends CoreTypeConverterRegistry {
52	
53	    public static final String META_INF_SERVICES_UBER_TYPE_CONVERTER_LOADER
54	            = "META-INF/services/org/apache/camel/UberTypeConverterLoader";
55	    public static final String META_INF_SERVICES_TYPE_CONVERTER_LOADER
56	            = "META-INF/services/org/apache/camel/TypeConverterLoader";
57	    public static final String META_INF_SERVICES_FALLBACK_TYPE_CONVERTER
58	            = "META-INF/services/org/apache/camel/FallbackTypeConverter";
59	
60	    private static final Logger LOG = LoggerFactory.getLogger(BaseTypeConverterRegistry.class);
61	
62	    protected final List<TypeConverterLoader> typeConverterLoaders = new ArrayList<>();
63	    protected CamelContext camelContext;
64	    protected PackageScanClassResolver resolver;
65	    protected Injector injector;
66	
67	    protected BaseTypeConverterRegistry(CamelContext camelContext, PackageScanClassResolver resolver, Injector injector,
68	                                        boolean statisticsEnabled) {
69	        super(statisticsEnabled);
70	
71	        this.camelContext = camelContext;
72	        this.injector = injector;
73	        this.resolver = resolver;
74	    }
75	
76	    @Override
77	    public CamelContext getCamelContext() {
78	        return camelContext;
79	    }
80	
81	    @Override
82	    public void setCamelContext(CamelContext camelContext) {
83	        this.camelContext = camelContext;
84	    }
85	
86	    public List<TypeConverterLoader> getTypeConverterLoaders() {
87	        return typeConverterLoaders;
88	    }
89	
90	    @Override
91	    public void addTypeConverters(Object typeConverters) {
92	        LOG.trace("Adding type converters: {}", typeConverters);
93	        try {
94	            // scan the class for @Converter and load them into this registry
95	            TypeConvertersLoader loader;
96	            if (typeConverters instanceof Class tcs) {
97	                loader = new TypeConvertersLoader(tcs);
98	            } else {
99	                loader = new TypeConvertersLoader(typeConverters);
100	            }
101	            CamelContextAware.trySetCamelContext(loader, getCamelContext());
102	            loader.load(this);
103	        } catch (TypeConverterLoaderException e) {
104	            throw RuntimeCamelException.wrapRuntimeCamelException(e);
105	        }
106	    }
107	
108	    @Override
109	    public void addFallbackTypeConverter(TypeConverter typeConverter, boolean canPromote) {
110	        super.addFallbackTypeConverter(typeConverter, canPromote);
111	        CamelContextAware.trySetCamelContext(typeConverter, camelContext);
112	    }
113	
114	    private void addCoreFallbackTypeConverterToList(
115	            TypeConverter typeConverter, boolean canPromote,
116	            List<FallbackTypeConverter> converters) {
117	        LOG.trace("Adding core fallback type converter: {} which can promote: {}", typeConverter, canPromote);
118	
119	        // add in top of fallback as the toString() fallback will nearly always be able to convert
120	        // the last one which is add to the FallbackTypeConverter will be called at the first place
121	        converters.add(0, new FallbackTypeConverter(typeConverter, canPromote));
122	
123	        CamelContextAware.trySetCamelContext(typeConverter, camelContext);
124	    }
125	
126	    @Override
127	    public Injector getInjector() {
128	        return injector;
129	    }
130	
131	    @Override
132	    public void setInjector(Injector injector) {
133	        this.injector = injector;
134	    }
135	
136	    public PackageScanClassResolver getResolver() {
137	        return resolver;
138	    }
139	
140	    /**
141	     * Loads the core type converters which is mandatory to use Camel, and also loads the fast type converters
142	     * (generated via @Converter(loader = true).
143	     */
144	    public void loadCoreAndFastTypeConverters() throws Exception {
145	        Collection<String> names = findTypeConverterLoaderClasses();
146	
147	        for (String name : names) {
148	            LOG.debug("Resolving TypeConverterLoader: {}", name);
149	            Class<?> clazz = null;
150	            for (ClassLoader loader : getResolver().getClassLoaders()) {
151	                try {
152	                    clazz = loader.loadClass(name);
153	                } catch (Exception e) {
154	                    // ignore
155	                }
156	                if (clazz != null) {
157	                    break;
158	                }
159	            }
160	            if (clazz == null) {
161	                throw new ClassNotFoundException(name);
162	            }
163	            Object obj = getInjector().newInstance(clazz, false);
164	            CamelContextAware.trySetCamelContext(obj, getCamelContext());
165	            if (obj instanceof TypeConverterLoader loader) {
166	                CamelContextAware.trySetCamelContext(loader, getCamelContext());
167	                LOG.debug("TypeConverterLoader: {} loading converters", name);
168	                loader.load(this);
169	            }
170	        }
171	    }
172	
173	    /**
174	     * Finds the type converter loader classes from the classpath looking for text files on the classpath at the
175	     * {@link #META_INF_SERVICES_UBER_TYPE_CONVERTER_LOADER} and {@link #META_INF_SERVICES_TYPE_CONVERTER_LOADER}
176	     * locations.
177	     */
178	    protected Collection<String> findTypeConverterLoaderClasses() throws IOException {
179	        Collection<String> loaders = new LinkedHashSet<>();
180	        findTypeConverterLoaderClasses(loaders, META_INF_SERVICES_UBER_TYPE_CONVERTER_LOADER);
181	        findTypeConverterLoaderClasses(loaders, META_INF_SERVICES_TYPE_CONVERTER_LOADER);
182	        return loaders;
183	    }
184	
185	    protected void findTypeConverterLoaderClasses(Collection<String> loaders, String basePath) throws IOException {
186	        Collection<URL> loaderResources = getLoaderUrls(basePath);
187	        for (URL url : loaderResources) {
188	            LOG.debug("Loading file {} to retrieve list of type converters, from url: {}",
189	                    basePath, url);
190	            BufferedReader reader = IOHelper.buffered(new InputStreamReader(url.openStream(), StandardCharsets.UTF_8));
191	            String line;
192	            do {
193	                line = reader.readLine();
194	                if (line != null && !line.startsWith("#") && !line.isEmpty()) {
195	                    loaders.add(line);
196	                }
197	            } while (line != null);
198	            IOHelper.close(reader);
199	        }
200	    }
201	
202	    protected Collection<URL> getLoaderUrls(String basePath) throws IOException {
203	        List<URL> loaderResources = new ArrayList<>();
204	        addResources(basePath, loaderResources);
205	        return loaderResources;
206	    }
207	
208	    /**
209	     * Checks if the registry is loaded and if not lazily load it
210	     */
211	    protected void loadTypeConverters() throws Exception {
212	        for (TypeConverterLoader loader : getTypeConverterLoaders()) {
213	            CamelContextAware.trySetCamelContext(loader, getCamelContext());
214	            loader.load(this);
215	        }
216	
217	        // lets try load any other fallback converters
218	        try {
219	            loadFallbackTypeConverters();
220	        } catch (NoFactoryAvailableException e) {
221	            // ignore its fine to have none
222	        }
223	    }
224	
225	    /**
226	     * Finds the fallback type converter classes from the classpath looking for text files on the classpath at the
227	     * {@link #META_INF_SERVICES_FALLBACK_TYPE_CONVERTER} location.
228	     */
229	    protected Collection<String> findFallbackTypeConverterClasses() throws IOException {
230	        Set<String> loaders = new LinkedHashSet<>();
231	        Collection<URL> loaderResources = getFallbackUrls();
232	        for (URL url : loaderResources) {
233	            LOG.debug("Loading file {} to retrieve list of fallback type converters, from url: {}",
234	                    META_INF_SERVICES_FALLBACK_TYPE_CONVERTER, url);
235	            BufferedReader reader = IOHelper.buffered(new InputStreamReader(url.openStream(), StandardCharsets.UTF_8));
236	            try {
237	                reader.lines()
238	                        .map(String::trim)
239	                        .filter(l -> !l.isEmpty())
240	                        .filter(l -> !l.startsWith("#"))
241	                        .forEach(loaders::add);
242	            } finally {
243	                IOHelper.close(reader, url.toString(), LOG);
244	            }
245	        }
246	        return loaders;
247	    }
248	
249	    protected Collection<URL> getFallbackUrls() throws IOException {
250	        List<URL> loaderResources = new ArrayList<>();
251	        addResources(META_INF_SERVICES_FALLBACK_TYPE_CONVERTER, loaderResources);
252	        return loaderResources;
253	    }
254	
255	    private void addResources(String metaInfServicesFallbackTypeConverter, List<URL> loaderResources) throws IOException {
256	        for (ClassLoader classLoader : resolver.getClassLoaders()) {
257	            Enumeration<URL> resources = classLoader.getResources(metaInfServicesFallbackTypeConverter);
258	            while (resources.hasMoreElements()) {
259	                URL url = resources.nextElement();
260	                loaderResources.add(url);
261	            }
262	        }
263	    }
264	
265	    protected void loadFallbackTypeConverters() throws IOException, ClassNotFoundException {
266	        Collection<String> names = findFallbackTypeConverterClasses();
267	        for (String name : names) {
268	            LOG.debug("Resolving FallbackTypeConverter: {}", name);
269	            Class<?> clazz = getResolver().getClassLoaders().stream()
270	                    .map(cl -> ObjectHelper.loadClass(name, cl))
271	                    .filter(Objects::nonNull)
272	                    .findAny().orElseThrow(() -> new ClassNotFoundException(name));
273	            Object obj = getInjector().newInstance(clazz, false);
274	            if (obj instanceof TypeConverter fb) {
275	                LOG.debug("Adding loaded FallbackTypeConverter: {}", name);
276	                addFallbackTypeConverter(fb, false);
277	            }
278	        }
279	    }
280	
281	    @Override
282	    protected void doInit() throws Exception {
283	        super.doInit();
284	
285	        if (injector == null && camelContext != null) {
286	            injector = camelContext.getInjector();
287	        }
288	        if (resolver == null && camelContext != null) {
289	            resolver = PluginHelper.getPackageScanClassResolver(camelContext);
290	        }
291	
292	        List<FallbackTypeConverter> fallbacks = new ArrayList<>();
293	        // add to string first as it will then be last in the last as to string can nearly
294	        // always convert something to a string so we want it only as the last resort
295	        // ToStringTypeConverter should NOT allow to be promoted
296	        addCoreFallbackTypeConverterToList(new ToStringTypeConverter(), false, fallbacks);
297	        // arrays is okay to be promoted
298	        addCoreFallbackTypeConverterToList(new ArrayTypeConverter(), true, fallbacks);
299	        // and future should also not allowed to be promoted
300	        addCoreFallbackTypeConverterToList(new FutureTypeConverter(this), false, fallbacks);
301	        // add sync processor to async processor converter is to be promoted
302	        addCoreFallbackTypeConverterToList(new AsyncProcessorTypeConverter(), true, fallbacks);
303	
304	        // add all core fallback converters at once which is faster (profiler)
305	        fallbackConverters.addAll(fallbacks);
306	    }
307	
308	}
