18	package org.apache.camel.spi;
19	
20	import java.util.Objects;
21	
22	import org.jspecify.annotations.Nullable;
23	
24	import static org.apache.camel.util.ObjectHelper.convertPrimitiveTypeToWrapperType;
25	
26	/**
27	 * Holds a type convertible pair. That is, consider 2 types defined as F and T, it defines that F can be converted to T.
28	 *
29	 * @param <F> The "from" type
30	 * @param <T> The "to" type.
31	 * @since     4.2
32	 */
33	public final class TypeConvertible<F, T> {
34	    private final Class<F> from;
35	    private final Class<T> to;
36	    private final int hash;
37	
38	    /**
39	     * Constructs a new type convertible pair. This is likely only used by core camel code and auto-generated bulk
40	     * loaders. This is an internal API and not meant for end users.
41	     *
42	     * @param from The class instance that defines the "from" type (that is: Class&lt;F&gt;.class). Must NOT be null.
43	     * @param to   The class instance that defines the "to" type (that is: Class&lt;F&gt;.class). Must NOT be null.
44	     */
45	    public TypeConvertible(Class<F> from, Class<T> to) {
46	        this.from = Objects.requireNonNull(from, "from");
47	        this.to = Objects.requireNonNull(to, "to");
48	
49	        this.hash = calculateHash();
50	    }
51	
52	    /**
53	     * Tests whether there is a conversion match from this TypeConvertible to the given TypeConvertible.
54	     *
55	     * For instance, consider 2 TypeConvertibles defined as "tc1{from: Number.class, to: String.class}" and "tc2{from:
56	     * Integer.class, to: String.class}", it traverses the type hierarchy of the "from" class to determine if it, or any
57	     * of its superclasses or any of its interfaces match with the "from" type of this instance.
58	     *
59	     * @param  that the TypeConvertible being tested against this instance
60	     * @return      true if there is a conversion match between the give TypeConvertible and this instance.
61	     */
62	    public boolean matches(TypeConvertible<?, ?> that) {
63	        Objects.requireNonNull(that, "that");
64	        return match(this.from, this.to, that.from, that.to);
65	    }
66	
67	    /**
68	     * Tests whether there is a conversion match from this TypeConvertible to the given TypeConvertible when the "to"
69	     * type of the tested TypeConvertible is a primitive type. See {@link TypeConvertible#matches(TypeConvertible)} for
70	     * details.
71	     *
72	     * @param  that the TypeConvertible being tested against this instance
73	     * @return      true if there is a conversion match between the give TypeConvertible and this instance.
74	     */
75	    public boolean matchesPrimitive(@Nullable TypeConvertible<?, ?> that) {
76	        if (that != null && that.getTo() != null) {
77	            return match(this.from, this.to, that.from, convertPrimitiveTypeToWrapperType(that.to));
78	        }
79	
80	        return false;
81	    }
82	
83	    /**
84	     * A recursive implementation of the type match algorithm.
85	     *
86	     * @param  thisFrom The class instance that defines the source "from" type (that is: Class&lt;F&gt;.class)
87	     * @param  thisTo   The class instance that defines the source "to" type (that is: Class&lt;F&gt;.class)
88	     * @param  thatFrom The class instance that defines the target "from" type (that is: Class&lt;F&gt;.class)
89	     * @param  thatTo   The class instance that defines the source "to" type (that is: Class&lt;F&gt;.class)
90	     * @return          true if there is a conversion match between the source types to the target types
91	     */
92	    private static boolean match(
93	            Class<?> thisFrom, Class<?> thisTo, @Nullable Class<?> thatFrom,
94	            @Nullable Class<?> thatTo) {
95	        if (thatFrom == null || thatTo == null) {
96	            return false;
97	        }
98	
99	        // Try direct
100	        if (directMatch(thisFrom, thisTo, thatFrom, thatTo)) {
101	            return true;
102	        }
103	
104	        // They are the same, but the thisTo and thatTo don't match.
105	        if (thisFrom == thatFrom) {
106	            return false;
107	        }
108	
109	        /* Try interfaces:
110	         * Try to resolve a TypeConverter by looking at the interfaces implemented by a given "from" type. It looks at the
111	         * type hierarchy of the target "from type" trying to match a suitable converter (i.e.: Integer -> Number). It will
112	         * recursively analyze the whole hierarchy.
113	         */
114	        final Class<?>[] interfaceTypes = thatFrom.getInterfaces();
115	        for (Class<?> interfaceType : interfaceTypes) {
116	            if (match(thisFrom, thisTo, interfaceType, thatTo)) {
117	                return true;
118	            }
119	        }
120	
121	        /*
122	         * Try to resolve a TypeConverter by looking at the parent class of a given "from" type. It looks at the type
123	         * hierarchy of the "from type" trying to match a suitable converter (i.e.: Integer -> Number). It will recursively
124	         * analyze the whole hierarchy, and it will also evaluate the interfaces implemented by such type.
125	         */
126	        return match(thisFrom, thisTo, thatFrom.getSuperclass(), thatTo);
127	    }
128	
129	    /**
130	     * Tests whether the types defined in this type convertable pair are assignable from another type convertable pair
131	     *
132	     * @param  that the type convertible pair to test
133	     * @return      true if the types in this instance are assignable from the respective types in the given type
134	     *              convertible
135	     */
136	    public boolean isAssignableMatch(TypeConvertible<?, ?> that) {
137	        Objects.requireNonNull(that, "that");
138	        return isAssignableMatch(this.from, this.to, that.from, that.to);
139	    }
140	
141	    private static boolean isAssignableMatch(Class<?> thisFrom, Class<?> thisTo, Class<?> thatFrom, Class<?> thatTo) {
142	        if (thisFrom == Object.class) {
143	            return false;
144	        }
145	
146	        if (thisTo.isAssignableFrom(thatTo)) {
147	            return thisFrom.isAssignableFrom(thatFrom);
148	        }
149	
150	        return false;
151	    }
152	
153	    /**
154	     * Try a direct match conversion (i.e.: those which the type conversion pair have a direct entry on the converters)
155	     *
156	     * @param  thisFrom The class instance that defines the source "from" type (that is: Class&lt;F&gt;.class)
157	     * @param  thisTo   The class instance that defines the source "to" type (that is: Class&lt;F&gt;.class)
158	     * @param  thatFrom The class instance that defines the target "from" type (that is: Class&lt;F&gt;.class)
159	     * @param  thatTo   The class instance that defines the source "to" type (that is: Class&lt;F&gt;.class)
160	     * @return          true if the types match directly or false otherwise
161	     */
162	
163	    private static boolean directMatch(Class<?> thisFrom, Class<?> thisTo, Class<?> thatFrom, Class<?> thatTo) {
164	        if (Objects.equals(thisFrom, thatFrom)) {
165	            return Objects.equals(thisTo, thatTo);
166	        }
167	
168	        return false;
169	    }
170	
171	    @Override
172	    public boolean equals(@Nullable Object o) {
173	        if (this == o) {
174	            return true;
175	        }
176	        if (o == null || getClass() != o.getClass()) {
177	            return false;
178	        }
179	
180	        TypeConvertible<?, ?> that = (TypeConvertible<?, ?>) o;
181	        return directMatch(this.from, this.to, that.from, that.to);
182	    }
183	
184	    @Override
185	    public int hashCode() {
186	        return hash;
187	    }
188	
189	    private int calculateHash() {
190	        int result = 1;
191	
192	        result = 31 * result + from.hashCode();
193	        result = 31 * result + to.hashCode();
194	
195	        return result;
196	    }
197	
198	    /**
199	     * Gets the class instance that defines the "from" type (that is: Class&lt;F&gt;.class)
200	     *
201	     * @return the "from" class instance
202	     */
203	    public Class<F> getFrom() {
204	        return from;
205	    }
206	
207	    /**
208	     * Gets the class instance that defines the "to" type (that is: Class&lt;F&gt;.class).
209	     *
210	     * @return the "to" class instance
211	     */
212	    public Class<T> getTo() {
213	        return to;
214	    }
215	
216	    @Override
217	    public String toString() {
218	        return "TypeConvertible{" +
219	               "from=" + from +
220	               ", to=" + to +
221	               '}';
222	    }
223	}
